import{z as o,x as s,o as B,c as d,q as n,j as t,D as A,d as a,s as r,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"嵌入的选型与微调","description":"","frontmatter":{"title":"嵌入的选型与微调","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rag-embedding-selection.md","filePath":"llm/rag-embedding-selection.md","lastUpdated":1791063341000}'),m={name:"llm/rag-embedding-selection.md"};function p(F,E,C,D,h,f){const l=s("Mermaid");return B(),d("div",null,[E[2]||(E[2]=n('<h1 id="嵌入的选型与微调" tabindex="-1">嵌入的选型与微调 <a class="header-anchor" href="#嵌入的选型与微调" aria-label="Permalink to &quot;嵌入的选型与微调&quot;">​</a></h1><div class="epigraph"><p>榜单分数是别人语料上的均值；你的召回是你自己查询分布上的分位数。选型与微调的全部纪律，就是把评测搬回自己的分布。</p><footer>—— 据 Muennighoff 等 MTEB 与检索嵌入工程实践整理</footer></div><p><a href="/llm/rag-chunking-deep">上一课</a>把切分写成受控比较：金标跨度固定，四族策略各在哪种语料上赢。切分定义了检索对象，本课给对象定度量：嵌入模型怎么选、什么时候值得微调、微调的数据从哪来、怎么不把通用能力调坏。对比损失的第一性在<a href="/llm/contrastive-infonce">对比学习与 InfoNCE</a>，难负例在<a href="/llm/hard-negatives">难负例挖掘</a>；本课不重推公式，只写选型与微调的工程协议。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>公开榜单（MTEB 一类）的域、语言、块长与你的语料不一致：榜首模型在内部工单、代码库、法律条款上可能反输给低几名的对手，因为榜单的检索任务多是网页短段。选型还有系统耦合：维度与块长连着上一课的切分，也连着下一课的索引内存；多语需求、最大输入长度、许可证、嵌入服务延迟都在约束里。微调的诱惑与风险并存：域内对比微调常能明显涨召回，但会把「同主题」压得过细、丢失通用改写能力，且合成训练对本身带偏——用 LLM 从块生成问题，模型学会的是「块风格的问题」，用户口语是另一种分布。</p><p><span class="marginnote">直觉类比：榜单分数像全国统考平均分——它说明模型「总体不差」；可你的语料是另一张卷子，考的是工单缩写、内部产品号。统考状元来答你的卷子，完全可能输给一个默默无闻但练过你这类题的模型。所以选型只认自建验证集，榜单只用来筛掉明显不合格的。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选型协议：自建验证查询集，从真实查询日志采样，并保留困难切片——标识符、否定、时间约束、跨语言改写；金标沿用上一课的支撑跨度，报「完整覆盖召回率」而不是榜单分数；同时记录维度、最大输入、多语能力、延迟与许可证五项约束。维度选择连着<a href="/llm/matryoshka-embeddings">Matryoshka 表示</a>：若候选模型支持前缀截断，内存与延迟就有粗到细的余地。</p><p>微调协议分四步。数据：用户点击（有位置偏置，要纠偏或降权）、LLM 合成查询（快但分布窄）、人工标注（贵而准），三者按域配比；负例用当前模型挖掘——排得高但不含答案的块，再混入批内随机负例防噪声主导。训练：InfoNCE 温度不乱动，学习率小、轮数少、早停，混入通用检索语料防遗忘。评测：域内与通用两套都必须报，只报域内看不到遗忘。验收：金标跨度覆盖 + 端到端忠实度，微调后重切不必但必须全量重嵌与重建索引。</p><p><span class="marginnote">数字实例：一个 1024 维、fp32 存储的向量占 \\(1024\\times4\\) 字节 = 4 KB；一千万条就是约 40 GB，还没算索引图的邻居表。若模型支持 Matryoshka 前缀截断，砍到 256 维就省到约 10 GB——这正是「维度」要写进选型约束表的原因：它直接连着内存账单。</span></p>',10)),(B(),t(i,null,{default:A(()=>[r(l,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOG%5B%22%E7%9C%9F%E5%AE%9E%E6%9F%A5%E8%AF%A2%E6%97%A5%E5%BF%97%E9%87%87%E6%A0%B7%22%5D%20--%3E%20SLICE%5B%22%E5%9B%B0%E9%9A%BE%E5%88%87%E7%89%87%EF%BC%9A%E6%A0%87%E8%AF%86%E7%AC%A6%20%2F%20%E5%90%A6%E5%AE%9A%20%2F%20%E6%97%B6%E9%97%B4%22%5D%0A%20%20SLICE%20--%3E%20CAND%5B%22%E5%80%99%E9%80%89%E6%A8%A1%E5%9E%8B%E8%B7%91%E8%A6%86%E7%9B%96%E5%8F%AC%E5%9B%9E%E7%8E%87%22%5D%0A%20%20CAND%20--%3E%20DEC%7B%22%E5%9F%9F%E5%86%85%E5%B7%AE%E8%B7%9D%E6%98%AF%E5%90%A6%E5%80%BC%E5%BE%97%E5%BE%AE%E8%B0%83%22%7D%0A%20%20DEC%20--%3E%7C%E5%90%A6%7C%20USE%5B%22%E7%9B%B4%E6%8E%A5%E7%94%A8%EF%BC%8C%E9%94%81%E7%89%88%E6%9C%AC%22%5D%0A%20%20DEC%20--%3E%7C%E6%98%AF%7C%20DATA%5B%22%E5%90%88%E6%88%90%20%2B%20%E7%82%B9%E5%87%BB%20%2B%20%E6%A0%87%E6%B3%A8%E9%85%8D%E6%AF%94%22%5D%0A%20%20DATA%20--%3E%20HN%5B%22%E5%BD%93%E5%89%8D%E6%A8%A1%E5%9E%8B%E6%8C%96%E9%9A%BE%E8%B4%9F%E4%BE%8B%22%5D%0A%20%20HN%20--%3E%20FT%5B%22%E5%B0%8F%E5%AD%A6%E4%B9%A0%E7%8E%87%E5%AF%B9%E6%AF%94%E5%BE%AE%E8%B0%83%22%5D%0A%20%20FT%20--%3E%20EV%5B%22%E5%9F%9F%E5%86%85%20%2B%20%E9%80%9A%E7%94%A8%E5%8F%8C%E8%AF%84%E6%B5%8B%22%5D%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("微调为什么涨：对比微调把度量从「同主题」推进到「含答案」，等价于把难负例的边界推开——这正是难负例课的机制在域内的重放。为什么常常不必：通用模型已在十亿级弱监督对上训练，几百条域内标注只能修正明显错位，收益上界还受切分质量限制——训练对里的「正例块」若是上一课说的碎片，模型学到的是碎片分类器。为什么不微调也别乱换：榜上零点几分的差距多在噪声内，换模型的全量重索引成本远大于分数差。指令前缀是中间态："),e("a",{href:"/llm/instruction-embeddings"},"指令嵌入"),a("用查询侧指令改变度量条件，不动权重，适合任务多样的系统先试。")],-1)),(B(),t(i,null,{default:A(()=>[r(l,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20BASE%5B%22%E9%80%9A%E7%94%A8%E5%B5%8C%E5%85%A5%E6%A8%A1%E5%9E%8B%3A%20%E5%8D%81%E4%BA%BF%E7%BA%A7%E5%BC%B1%E7%9B%91%E7%9D%A3%E5%AF%B9%22%5D%20--%3E%20FT%5B%22%E5%87%A0%E7%99%BE%E6%9D%A1%E5%9F%9F%E5%86%85%E5%AF%B9%E6%AF%94%E5%BE%AE%E8%B0%83%22%5D%0A%20%20FT%20--%3E%20GAIN%5B%22%E5%9F%9F%E5%86%85%E3%80%8E%E5%90%AB%E7%AD%94%E6%A1%88%E3%80%8F%E5%BA%A6%E9%87%8F%E6%9B%B4%E5%87%86%2C%20%E5%8F%AC%E5%9B%9E%E6%B6%A8%22%5D%0A%20%20FT%20--%3E%20RISK1%5B%22%E3%80%8E%E5%90%8C%E4%B8%BB%E9%A2%98%E3%80%8F%E5%8E%8B%E5%BE%97%E8%BF%87%E7%BB%86%2C%20%E6%94%B9%E5%86%99%E5%8C%B9%E9%85%8D%E5%8F%98%E5%B7%AE%22%5D%0A%20%20FT%20--%3E%20RISK2%5B%22%E9%80%9A%E7%94%A8%E6%A3%80%E7%B4%A2%E8%83%BD%E5%8A%9B%E8%A2%AB%E8%A6%86%E7%9B%96%3A%20%E9%81%97%E5%BF%98%22%5D%0A%20%20RISK2%20--%3E%20GATE%5B%22%E9%80%9A%E7%94%A8%E9%9B%86%E8%AF%84%E6%B5%8B%E5%BF%85%E9%A1%BB%E7%85%A7%E5%B8%B8%E6%8A%A5%E5%88%86%22%5D%0A%20%20GAIN%20--%3E%20GATE%0A%20%20GATE%20--%20%22%E4%B8%A4%E5%A5%97%E9%83%BD%E8%BF%87%22%20--%3E%20SHIP%5B%22%E9%94%81%E7%89%88%E6%9C%AC%E5%8F%91%E5%B8%83%22%5D%0A%20%20GATE%20--%20%22%E9%80%9A%E7%94%A8%E5%A1%8C%E4%BA%86%22%20--%3E%20BACK%5B%22%E9%80%80%E5%9B%9E%E6%8C%87%E4%BB%A4%E5%89%8D%E7%BC%80%20%2F%20%E5%8F%AA%E8%B0%83%E9%87%8D%E6%8E%92%22%5D%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=n('<p><span class="marginnote">常见误区：初学者容易把微调后的域内指标上涨全当成收益。若同一时间通用集掉了十几个点，说明模型把「域内少数几类查询」背下来了，遇到换种问法的真实用户就会露馅——所以协议要求两套评测同台报，缺一不可。</span></p><p><span class="marginnote">换嵌入模型 = 全量重嵌 + 重建索引 + 可能重切，且融合权重、重排器难负例分布全部作废。把「换嵌入」当一次发布，走三角门禁，而不是当一次配置修改。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>微调过的模型不保证向其他域迁移，换语料大版本要重测；多语场景下微调数据若单语偏重，跨语言对齐会退化。多模态查询是另一套嵌入空间，见<a href="/llm/multimodal-embeddings">多模态嵌入</a>，本课不混谈。嵌入服务的批处理与缓存属于延迟工程，后面专课处理。选型与微调都完成后，向量空间就绪，下一步是把它变成能扛住千万级库与延迟预算的索引——参数学见下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>榜单是别人分布上的均值，选型只认自建验证集上的覆盖召回率与五项系统约束。</li><li>微调数据三源配比：合成、点击、标注；负例靠当前模型挖，混随机负例防噪。</li><li>小学习率、早停、混通用语料防遗忘；域内与通用双评测缺一不可。</li><li>指令前缀是不动权重的中间态；Matryoshka 给维度留粗到细余地。</li><li>换嵌入是发布级动作：全量重索引并重跑门禁。</li><li>出处：Muennighoff 等 MTEB；van den Oord 等 InfoNCE；Xiong 等 ANCE；据工程实践整理。</li></ul>',6))])}const u=o(m,[["render",p]]);export{T as __pageData,u as default};
